class SubmitLoanRequestModule_AutoGenerated {
  /*find a loan request with provided request id, if the loan request is not exist, create a new loan request with provided info and save it, then the current loan request is it*/
  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let loanRequest: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (lr: any) =>
            l({
              logic: () => lr.RequestID === requestid,
              description: "lr.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(lr|lr.RequestID=requestid)",
    }).build().pass;
    let newLoanRequest: LoanRequest = l({
      logic: () => undefined,
      description: "null",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(loanRequest) === true,
        description: "loanRequest.oclIsUndefined()=true",
      })
        .or({
          logic: () => StandardOPs.oclIsUndefined(loanRequest) === false,
          description: "loanRequest.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let tempNewLoanRequest: LoanRequest;
    return l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(loanRequest) === true,
            description: "loanRequest.oclIsUndefined()=true",
          }),
        description: "loanRequest.oclIsUndefined()=true",
        then: l({
          execute: () => (tempNewLoanRequest = new LoanRequest()),
          description: "tempNewLoanRequest.oclIsNew()",
        })
          .and({
            execute: () => getRepository(LoanRequest).push(tempNewLoanRequest),
            description:
              "LoanRequest.allInstance()->includes(tempNewLoanRequest)",
          })
          .and({
            execute: () => (tempNewLoanRequest.RequestID = requestid),
            description: "tempNewLoanRequest.RequestID=requestid",
          })
          .and({
            execute: () => (tempNewLoanRequest.Name = name),
            description: "tempNewLoanRequest.Name=name",
          })
          .and({
            execute: () => (tempNewLoanRequest.LoanAmount = loanamount),
            description: "tempNewLoanRequest.LoanAmount=loanamount",
          })
          .and({
            execute: () => (tempNewLoanRequest.LoanPurpose = loanpurpose),
            description: "tempNewLoanRequest.LoanPurpose=loanpurpose",
          })
          .and({
            execute: () => (tempNewLoanRequest.Income = income),
            description: "tempNewLoanRequest.Income=income",
          })
          .and({
            execute: () => (tempNewLoanRequest.PhoneNumber = phonenumber),
            description: "tempNewLoanRequest.PhoneNumber=phonenumber",
          })
          .and({
            execute: () => (tempNewLoanRequest.PostalAddress = postaladdress),
            description: "tempNewLoanRequest.PostalAddress=postaladdress",
          })
          .and({
            execute: () => (tempNewLoanRequest.ZipCode = zipcode),
            description: "tempNewLoanRequest.ZipCode=zipcode",
          })
          .and({
            execute: () => (tempNewLoanRequest.Email = email),
            description: "tempNewLoanRequest.Email=email",
          })
          .and({
            execute: () => (tempNewLoanRequest.WorkReferences = workreferences),
            description: "tempNewLoanRequest.WorkReferences=workreferences",
          })
          .and({
            execute: () =>
              (tempNewLoanRequest.CreditReferences = creditreferences),
            description: "tempNewLoanRequest.CreditReferences=creditreferences",
          })
          .and({
            execute: () =>
              (tempNewLoanRequest.CheckingAccountNumber =
                checkingaccountnumber),
            description:
              "tempNewLoanRequest.CheckingAccountNumber=checkingaccountnumber",
          })
          .and({
            execute: () => (tempNewLoanRequest.SecurityNumber = securitynumber),
            description: "tempNewLoanRequest.SecurityNumber=securitynumber",
          })
          .and({
            execute: () => (this.CurrentLoanRequest = tempNewLoanRequest),
            description: "self.CurrentLoanRequest=tempNewLoanRequest",
          })
          .and({
            execute: () => true,
            description: "result=true",
          }),
        else: l({
          execute: () => (this.CurrentLoanRequest = loanRequest),
          description: "self.CurrentLoanRequest=loanRequest",
        }).and({
          execute: () => true,
          description: "result=true",
        }),
      })
      .build().value;
    /*Postcondition End*/
  }
}
